#!/usr/bin/env bash
set -u
echo "=== 安装 xinmo-bridge 代理 ==="
sudo mkdir -p /opt/xinmo-bridge
echo '' | base64 -d | sudo tee /opt/xinmo-bridge/agent.py >/dev/null
sudo chmod 600 /opt/xinmo-bridge/agent.py
echo "=== 创建 systemd 服务 ==="
sudo tee /etc/systemd/system/xinmo-bridge.service >/dev/null <<'EOF'
[Unit]
Description=xinmo.work remote command bridge
After=network-online.target
Wants=network-online.target
[Service]
Type=simple
User=root
WorkingDirectory=/opt/xinmo-bridge
ExecStart=/usr/bin/python3 /opt/xinmo-bridge/agent.py
Restart=always
RestartSec=5
StandardOutput=append:/var/log/xinmo-bridge.log
StandardError=append:/var/log/xinmo-bridge.log
[Install]
WantedBy=multi-user.target
EOF
sudo systemctl daemon-reload
sudo systemctl enable xinmo-bridge
sudo systemctl restart xinmo-bridge
sleep 2
echo "=== 服务状态 ==="
sudo systemctl is-active xinmo-bridge
echo "=== 日志 ==="
sudo tail -5 /var/log/xinmo-bridge.log
echo "=== DONE ==="
